import { MessageConfig } from 'espd-common/i18n';

export type ActionsGenerator = (obj: any) => ActionList | SingleAction | NoAction;
export type NoAction = null;

export interface Action {
	action?: () => void;
	route?: string;
	label: MessageConfig | string;
	disabled?: boolean;
}

export interface ActionList {
	actions: Action[];
	label: MessageConfig | string;
}

export class SingleAction implements Action {
	constructor(
		public label: MessageConfig | string,
		public action?: () => void,
		public hideLabel?: boolean,
		public route?: string,
		public icon?: string) { }

	public performAction(): void {
		this.action?.();
	}
}

export class ActionListSeparator implements Action {
	public action = undefined;
	public label = '';
}